var paths=new[]{"Assets/Prefabs/Player/Player.prefab","Assets/Prefabs/Weapons/Enemy_Entity.prefab","Assets/Prefabs/Bosses/SH10_L01_BossGameplay.prefab"};var added=0;foreach(var path in paths){var root=UnityEditor.PrefabUtility.LoadPrefabContents(path);try{var animator=root.GetComponentsInChildren<UnityEngine.Animator>(true).FirstOrDefault(a=>a.gameObject.name.Contains("SH10"));if(animator==null)throw new System.Exception("Integrated Animator missing: "+path);if(!animator.GetComponent<SoulHunter.Gameplay.Animation.EntityAnimator>()){animator.gameObject.AddComponent<SoulHunter.Gameplay.Animation.EntityAnimator>();added++;}UnityEditor.PrefabUtility.SaveAsPrefabAsset(root,path);}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}}UnityEditor.AssetDatabase.SaveAssets();return new{prefabs=paths.Length,bridgesAdded=added};
